-- Thế giới khối – đợt 2 (21/11/2026, người dùng: "cần tiếp tục…", "xóa 9 chặng còn lại vẫn dùng cảnh nhập vai 2D"): cả 13 chặng có nhiệm vụ thế giới khối.
--  - hk_world_awards: phần thưởng của học sinh trong thế giới khối – danh hiệu ("Người giữ làng", "Đồng lòng giữ nước"), tuyến vận chuyển đã mở,
--    trang Sổ sử Đông A đã hoàn thiện. RLS theo trường như các bảng hk_*, thu hồi quyền công khai, có kho lưu bản xóa.
--  - Bản đồ khối phần 1 (1258) và phần 2 (1285); nhiệm vụ của 9 chặng (khóa world của content; giữ nguyên content.explore cũ – không xóa dữ liệu).
--  - Bản đồ phần 3 (migration 080) thêm dấu ấn của em, trang Sổ sử; không đổi lưới ô / nhiệm vụ đã có.
-- Dữ kiện trong lời thoại lấy từ thẻ kiến thức / tổng kết đã có nguồn của từng chặng (migration 066). Nhân vật phụ, lời thoại, công thức, số lượng,
-- hiệu lệnh đội hình và chi tiết giúp Trần Quốc Toản làm cờ là phần sáng tạo của trò chơi.

CREATE TABLE public.hk_world_awards (
    user_id INTEGER NOT NULL REFERENCES public.app_users(id) ON DELETE CASCADE,
    code TEXT NOT NULL CHECK (code ~ '^(title|route|book):[a-z0-9-]{1,40}$'),
    earned_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, code)
);

DO $$
DECLARE own TEXT; rule TEXT; r TEXT;
BEGIN
    ALTER TABLE public.hk_world_awards ENABLE ROW LEVEL SECURITY;
    REVOKE ALL ON public.hk_world_awards FROM PUBLIC;
    FOREACH r IN ARRAY ARRAY['anon', 'authenticated', 'service_role'] LOOP
        IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN EXECUTE format('REVOKE ALL ON public.hk_world_awards FROM %I', r); END IF;
    END LOOP;
    own := 'public.app_workspace_owner(''public.hk_world_awards''::regclass, to_jsonb(hk_world_awards))';
    rule := format('((public.app_workspace_school() IS NOT NULL AND %s = public.app_workspace_school()) OR %s = -NULLIF(current_setting(''app.user_id'', true), '''')::integer)', own, own);
    GRANT SELECT, INSERT, UPDATE, DELETE ON public.hk_world_awards TO dong_a_workspace_scope;
    EXECUTE format('CREATE POLICY workspace_read ON public.hk_world_awards FOR SELECT TO dong_a_workspace_scope USING (%s)', rule);
    EXECUTE format('CREATE POLICY workspace_insert ON public.hk_world_awards FOR INSERT TO dong_a_workspace_scope WITH CHECK (%s)', rule);
    EXECUTE format('CREATE POLICY workspace_update ON public.hk_world_awards FOR UPDATE TO dong_a_workspace_scope USING (%s) WITH CHECK (%s)', rule, rule);
    EXECUTE format('CREATE POLICY workspace_delete ON public.hk_world_awards FOR DELETE TO dong_a_workspace_scope USING (%s)', rule);
END $$;
SELECT public.app_install_delete_archives();

