huẩn bị đã đưa đồng đội về lại kinh thành.","props":[{"kind":"boat","at":[23,9]},{"kind":"flag","at":[29,12]},{"kind":"villager","at":[12,9]}]},{"stage":"tay-ket","text":"Dân kinh thành ra đón quân thắng trận trở về.","props":[{"kind":"villager","at":[13,10]},{"kind":"villager","at":[5,6]},{"kind":"flag","at":[13,4]}]}],"book":{"title":"Kháng chiến lần thứ hai (1285)","events":[{"id":"binh_than","text":"Hội nghị Bình Than (cuối năm 1282): vương hầu, tướng lĩnh bàn kế đánh, kế phòng."},{"id":"dien_hong","text":"Hội nghị Diên Hồng (đầu năm 1285): các bô lão đồng thanh “Đánh!”."},{"id":"rut_lui","text":"Quân Trần rời Thăng Long; Trần Bình Trọng chặn giặc ở Đà Mạc (tháng 2/1285)."},{"id":"ham_tu","text":"Trần Nhật Duật thắng trận Hàm Tử (khoảng tháng 5/1285)."},{"id":"chuong_duong","text":"Trận Chương Dương, quân Trần giải phóng Thăng Long (tháng 6/1285)."},{"id":"tay_ket","text":"Trận Tây Kết (24/6/1285): Toa Đô tử trận."}]},"note":"Sa bàn khối là minh họa sáng tạo để chơi: khoảng cách, vị trí các nơi được thu gọn, không phải bản đồ địa lý. Công thức chế tạo, số lượng lều / thuyền / rào / bao lương, hiệu lệnh đội hình là quy ước của trò chơi."}$w$::jsonb WHERE campaign_no = 2 AND world IS NULL;

UPDATE public.hk_saga_maps SET world = world || $w${"routes":[],"changes":[{"stage":"chuan-bi-1287","text":"Chiến lũy ở cửa ải phía bắc đã có quân canh giữ.","props":[{"kind":"flag","at":[11,3]},{"kind":"fire","at":[13,4]}]},{"stage":"van-don","text":"Thuyền lương của giặc bị thu giữ, neo ở cầu tàu Vân Đồn.","props":[{"kind":"boat","at":[44,19]},{"kind":"flag","at":[42,18]}]},{"stage":"van-kiep-1288","text":"Kho lương trong núi đầy ắp, bà con yên tâm.","props":[{"kind":"granary","at":[29,5]},{"kind":"villager","at":[27,7]}]},{"stage":"bach-dang","text":"Làng ven sông đón quân thắng trận trở về.","props":[{"kind":"villager","at":[5,20]},{"kind":"villager","at":[7,20]},{"kind":"flag","at":[26,22]},{"kind":"boat","at":[32,26]}]}],"book":{"title":"Kháng chiến lần thứ ba (1287 – 1288)","events":[{"id":"phuc_thu","text":"Hốt Tất Liệt dồn sức đánh Đại Việt lần thứ ba (cuối năm 1287)."},{"id":"van_don","text":"Trần Khánh Dư đánh đoàn thuyền lương ở Vân Đồn (cuối 12/1287 – đầu 1/1288)."},{"id":"thang_long","text":"Quân Nguyên lại vào Thăng Long nhưng thiếu lương (đầu 2/1288)."},{"id":"van_kiep","text":"Thoát Hoan co cụm ở Vạn Kiếp rồi quyết định rút quân (cuối 3/1288)."},{"id":"bach_dang","text":"Trận Bạch Đằng (9/4/1288): Ô Mã Nhi bị bắt."}]}}$w$::jsonb WHERE campaign_no = 3 AND world IS NOT NULL AND NOT (world ? 'book');

UPDATE public.hk_saga_stages SET content = content || jsonb_build_object('world', $w${"title":"Giữ biên giới phía bắc","intro":"Cuối năm 1257, quân Mông Cổ áp sát biên giới. Em là một tiểu tướng trẻ (nhân vật hư cấu) theo vua Trần Thái Tông ra Bình Lệ Nguyên, rồi cùng Lê Tần che chở nhà vua khi quân Trần lui để giữ sức.","steps":[{"type":"talk","npc":"thai_tong","goal":"Tới trại Bình Lệ Nguyên gặp vua Trần Thái Tông.","lines":["Tướng Mông Cổ Ngột Lương Hợp Thai sai sứ sang dụ hàng. Triều đình đã giam sứ giả, đem quân thủy bộ lên giữ biên giới.","Ta sẽ đích thân bày voi chiến, kỵ binh và bộ binh bên sông chờ giặc. Em chuẩn bị ván gỗ phòng tên."]},{"type":"gather","res":"go","count":2,"goal":"Lấy 2 gỗ ở khu rừng phía nam trại."},{"type":"craft","item":"van","count":2,"goal":"Tới bàn chế tạo, làm 2 ván che tên (mỗi ván 1 gỗ)."},{"type":"battle","zone":"binh_le","goal":"Ra đồng Bình Lệ Nguyên giao chiến cùng quân Trần."},{"type":"talk","npc":"le_tan","goal":"Gặp tướng Lê Tần sau trận đánh.","lines":["Giặc bắn tên vào mắt voi, voi đau hoảng loạn quay lại giẫm vào đội hình ta.","Ta đã can nhà vua đừng “đánh một ván dốc túi”. Lui quân giữ sức – ta sẽ đi sau che tên cho bệ hạ."]},{"type":"give","npc":"le_tan","item":"van","count":2,"goal":"Đưa 2 ván che tên cho Lê Tần.","lines":["Tốt lắm! Những tấm ván này sẽ che tên cho nhà vua khi quân ta lui."]},{"type":"zone","zone":"phu_lo","goal":"Theo đoàn quân lui về cầu Phù Lỗ.","lines":["Quân Trần lui có trật tự về Phù Lỗ, giữ được thuyền và lực lượng chủ lực.","Hôm sau, quân Trần chặt cầu Phù Lỗ để cản giặc rồi chủ động rời Thăng Long."]},{"type":"ask","npc":"le_tan","goal":"Trả lời câu hỏi của Lê Tần.","prompt":"Vì sao sau trận Bình Lệ Nguyên quân Trần lui quân?","options":[{"id":"a","text":"Vì quân Trần đã mất hết quân"},{"id":"b","text":"Để giữ lực lượng – giữ được quân thì còn ngày phản công"},{"id":"c","text":"Để xin hàng quân Mông Cổ"}],"correct":"b","right":"Đúng. Lui quân có trật tự, giữ được thuyền và chủ lực, là bước đầu của thắng lợi về sau.","wrong":"Chưa đúng. Nhớ lại lời ta khuyên nhà vua về “ván dốc túi”."}]}$w$::jsonb) WHERE code = 'binh-le-nguyen' AND NOT (content ? 'world');
UPDATE public.hk_saga_stages SET content = content || jsonb_build_object('world', $w${"title":"Sơ tán – vườn không nhà trống","intro":"Triều Trần ra lệnh cho dân cất giấu lương thực rồi rời kinh thành. Em cùng các bạn gặt lúa, tìm đúng bến thuyền, đưa bà con và lương thực xuống Thiên Mạc an toàn, dựng nơi trú tạm. Nhân vật của em và dân làng là hư cấu.","steps":[{"type":"talk","npc":"truong_lang","goal":"Về làng ven kinh thành gặp cụ trưởng làng.","lines":["Triều đình ra lệnh cho dân cất giấu hết lương thực rồi rời kinh thành.","Quân Mông Cổ đi nhanh, mang rất ít lương, chỉ trông vào cướp lương nơi chúng tới."]},{"type":"talk","npc":"ba_cu","goal":"Hỏi bà cụ trong làng cần giúp gì.","lines":["Nhà bà còn ít lúa ngoài đồng. Cháu gặt giúp, rồi tìm thuyền đưa bà con với lương thực xuống Thiên Mạc.","Thuyền xuống Thiên Mạc đậu ở bến xuôi nhất về phía nam của kinh thành."]},{"type":"gather","res":"lua","count":4,"goal":"Gặt 4 lúa ngoài đồng."},{"type":"craft","item":"bao","count":2,"goal":"Đóng 2 bao lương ở bàn chế tạo (mỗi bao 2 lúa)."},{"type":"pick","zones":["ben_hang_than","ben_cho","ben_nam"],"correct":"ben_nam","award":"route:song-hong-1258","goal":"Đọc bản đồ, tìm đúng bến có thuyền xuôi về Thiên Mạc.","clue":"Bến xuôi nhất về phía nam, nơi dòng sông chảy về Thiên Mạc.","right":"Đúng bến rồi! Người chèo thuyền đưa bà con và lương thực xuôi dòng về Thiên Mạc.","wrong":"Bến này không có thuyền đi Thiên Mạc. Xem lại bản đồ: bến nào xuôi nhất về phía nam?"},{"type":"place","item":"bao","zone":"kho_an","count":2,"team":4,"award":"title:nguoi-giu-lang","goal":"Tới Thiên Mạc, cất bao lương vào kho kín dưới chân núi: em cất 2, cả lớp cần 4."},{"type":"gather","res":"tre","count":4,"goal":"Lấy 4 tre để dựng nơi trú tạm."},{"type":"craft","item":"leu","count":2,"goal":"Làm 2 lều trú tạm (mỗi lều 2 tre)."},{"type":"place","item":"leu","zone":"trai_tam","count":2,"team":4,"goal":"Dựng lều cho bà con ở nơi trú tạm Thiên Mạc: em dựng 2, cả lớp cần 4."},{"type":"talk","npc":"thu_do","goal":"Gặp Thái sư Trần Thủ Độ ở Thiên Mạc.","lines":["Trên sông Thiên Mạc, khi nhà vua hỏi kế, có người viết hai chữ “nhập Tống” – sang lánh đất Tống.","Ta tâu với vua: “Đầu thần chưa rơi xuống đất, bệ hạ đừng lo gì khác.”"]},{"type":"ask","npc":"thu_do","goal":"Trả lời câu hỏi của Thái sư.","prompt":"Vì sao cất giấu lương thực rồi rời Thăng Long lại giúp cuộc kháng chiến?","options":[{"id":"a","text":"Vì kinh thành đã quá cũ"},{"id":"b","text":"Vì quân Mông Cổ trông vào cướp lương: kho trống thì giặc đói, còn quân ta giữ được lực lượng"},{"id":"c","text":"Vì giặc sẽ tự rút ngay khi thấy kinh thành"}],"correct":"b","right":"Đúng! Giặc vào Thăng Long chỉ thấy kho tàng trống rỗng; ta giữ được thuyền và chủ lực ở Thiên Mạc, chờ thời cơ phản công.","wrong":"Chưa đúng. Nhớ lời cụ trưởng làng về cách quân Mông Cổ kiếm lương."}]}$w$::jsonb) WHERE code = 'vuon-khong-nha-trong' AND NOT (content ? 'world');
UPDATE public.hk_saga_stages SET content = content || jsonb_build_object('world', $w${"title":"Phản công Đông Bộ Đầu","intro":"Giặc chiếm Thăng Long nhưng đói và chủ quan. Ở Thiên Mạc, em cùng các bạn chuẩn bị thuyền cho trận đánh úp lúc nửa đêm ở bến Đông Bộ Đầu.","steps":[{"type":"talk","npc":"tran_hoang","goal":"Tới Thiên Mạc gặp Thái tử Trần Hoảng.","lines":["Giặc chiếm Thăng Long nhưng kho tàng trống rỗng, thiếu lương. Thấy ta thua trận đầu, chúng rất chủ quan.","Đêm nay vua cha và ta sẽ ngự lâu thuyền ngược sông đánh úp. Hãy chuẩn bị thuyền."]},{"type":"gather","res":"go","count":4,"goal":"Lấy 4 gỗ để đóng thuyền."},{"type":"gather","res":"tre","count":2,"goal":"Lấy 2 tre."},{"type":"craft","item":"thuyen","count":2,"goal":"Đóng 2 thuyền nhẹ (mỗi chiếc 2 gỗ + 1 tre)."},{"type":"place","item":"thuyen","zone":"ben_tm","count":2,"team":4,"goal":"Đưa thuyền ra bến Thiên Mạc: em đưa 2 chiếc, cả lớp cần 4 chiếc."},{"type":"battle","zone":"dong_bo_dau","goal":"Ngược sông, đánh úp quân Mông Cổ ở bến Đông Bộ Đầu.","clue":"Đã mở tuyến thuyền Bến Nam ⇄ Thiên Mạc thì đi thuyền cho nhanh."},{"type":"talk","npc":"linh_tran","goal":"Gặp lính thuyền quân Trần ở Đông Bộ Đầu.","lines":["Giặc không kịp trở tay, thua to! Chúng bỏ Thăng Long, rút chạy về Vân Nam theo dọc sông Thao.","Tới Quy Hóa, giặc còn bị chủ trại Hà Bổng tập kích."]},{"type":"ask","npc":"linh_tran","goal":"Trả lời câu hỏi của người lính.","prompt":"Ba việc nào nối tiếp nhau làm nên thắng lợi năm 1258?","options":[{"id":"a","text":"Lui quân giữ lực lượng – cất giấu lương làm giặc đói – phản công bất ngờ khi giặc chủ quan"},{"id":"b","text":"Xin hàng – cầu hòa – rút lui"},{"id":"c","text":"Xây thành cao – đóng cửa thành – chờ giặc tự về"}],"correct":"a","right":"Đúng! Đó là bài học của cuộc kháng chiến lần thứ nhất.","wrong":"Chưa đúng. Nhớ lại Bình Lệ Nguyên, vườn không nhà trống và trận đêm nay."}]}$w$::jsonb) WHERE code = 'dong-bo-dau' AND NOT (content ? 'world');
UPDATE public.hk_saga_stages SET content = content || jsonb_build_object('world', $w${"title":"Hội nghị Bình Than","intro":"Cuối năm 1282, nhà Nguyên chuẩn bị đánh Đại Việt. Em tới bến Bình Than, nơi vua Trần Nhân Tông họp vương hầu và các tướng, rồi giúp chàng thiếu niên Trần Quốc Toản làm lá cờ ra trận (chi tiết làm cờ là sáng tạo của trò chơi).","steps":[{"type":"talk","npc":"nhan_tong","goal":"Tới bến Bình Than gặp vua Trần Nhân Tông.","lines":["Nhà Nguyên đã thôn tính Nam Tống và đang chuẩn bị đánh nước ta.","Ta họp vương hầu, tướng lĩnh ở Bình Than để bàn kế đánh, kế phòng và chia quân giữ nơi hiểm yếu."]},{"type":"talk","npc":"khanh_du","goal":"Gặp Trần Khánh Dư.","lines":["Ta đang mang tội, nhưng được tha để về dự hội nghị bàn việc nước.","Lúc nước nhà cần, người có tài đều được dùng."]},{"type":"talk","npc":"quoc_toan","goal":"Gặp chàng thiếu niên Trần Quốc Toản.","lines":["Ta còn nhỏ tuổi nên không được dự bàn. Tức quá, quả cam trong tay bị bóp nát lúc nào không hay!","Ta sẽ về quê tập hợp người, đóng chiến thuyền, dựng cờ sáu chữ “Phá cường địch, báo hoàng ân”. Em giúp ta làm lá cờ nhé."]},{"type":"gather","res":"tre","count":2,"goal":"Lấy 2 tre làm cán cờ."},{"type":"craft","item":"co","count":1,"goal":"Làm 1 cờ hiệu ở bàn chế tạo."},{"type":"give","npc":"quoc_toan","item":"co","count":1,"goal":"Trao lá cờ cho Trần Quốc Toản.","lines":["Lá cờ đây rồi! “Phá cường địch, báo hoàng ân” – ta sẽ cùng nghĩa quân ra trận."]},{"type":"ask","npc":"nhan_tong","goal":"Trả lời câu hỏi của nhà vua.","prompt":"Hội nghị Bình Than là hội nghị gì?","options":[{"id":"a","text":"Hội nghị hỏi ý các bô lão trong cả nước"},{"id":"b","text":"Hội nghị quân sự của vương hầu, tướng lĩnh bàn kế đánh, kế phòng, chia quân giữ nơi hiểm yếu"},{"id":"c","text":"Lễ mừng chiến thắng"}],"correct":"b","right":"Đúng. Hội nghị diễn ra cuối năm 1282, hơn hai năm trước khi giặc tràn sang.","wrong":"Chưa đúng. Hội nghị hỏi ý bô lão là Diên Hồng; Bình Than là hội nghị của vương hầu, tướng lĩnh."}]}$w$::jsonb) WHERE code = 'binh-than' AND NOT (content ? 'world');
UPDATE public.hk_saga_stages SET content = content || jsonb_build_object('world', $w${"title":"Diên Hồng – dựng quân doanh, luyện đội hình","intro":"Đầu năm 1285, giặc sắp tràn sang. Em nghe các bô lão ở điện Diên Hồng, rồi cùng các bạn dựng quân doanh và luyện phối hợp đội hình theo hiệu lệnh.","steps":[{"type":"talk","npc":"thanh_tong","goal":"Vào sân điện Diên Hồng gặp Thượng hoàng Trần Thánh Tông.","lines":["Giặc sắp tràn sang. Ta mời các bậc tuổi cao có uy tín trong cả nước về điện Diên Hồng để hỏi: có nên đánh lại quân Nguyên hay không?"]},{"type":"zone","zone":"dien","goal":"Đứng trước điện Diên Hồng nghe các bô lão trả lời.","lines":["Các bô lão đồng thanh: “Đánh!”","Sử chép: “vạn người cùng nói như từ một miệng”."]},{"type":"talk","npc":"quoc_tuan","goal":"Tới quân doanh gặp Quốc công Tiết chế Trần Quốc Tuấn.","lines":["Ta được phong Quốc công Tiết chế, thống lĩnh mọi lực lượng.","Ta đã viết Hịch tướng sĩ; nhiều chiến sĩ thích lên cánh tay hai chữ “Sát Thát”. Giờ hãy dựng quân doanh và luyện đội hình."]},{"type":"gather","res":"tre","count":4,"goal":"Lấy 4 tre để dựng lều quân doanh."},{"type":"craft","item":"leu","count":2,"goal":"Làm 2 lều (mỗi lều 2 tre)."},{"type":"place","item":"leu","zone":"quan_doanh","count":2,"team":4,"goal":"Dựng lều ở quân doanh: em dựng 2, cả lớp cần 4."},{"type":"drill","zones":["doi_1","doi_2","doi_3","doi_4","doi_5"],"award":"title:dong-long-giu-nuoc","goal":"Luyện phối hợp đội hình ở sân luyện quân: đi đúng thứ tự các vị trí theo hiệu lệnh.","commands":["Đứng vào hàng đầu, dưới cờ đỏ (vị trí 1).","Tiến sang bên phải, giữ thẳng hàng (vị trí 2).","Lùi về hàng sau bên trái, che cho đồng đội (vị trí 3).","Sang phải, khép kín hàng sau (vị trí 4).","Về vị trí chỉ huy, cả đội vào hàng (vị trí chỉ huy)."]},{"type":"ask","npc":"quoc_tuan","goal":"Trả lời câu hỏi của Trần Quốc Tuấn.","prompt":"Hội nghị Diên Hồng cho thấy điều gì?","options":[{"id":"a","text":"Triều đình hỏi ý dân và cả nước đồng lòng đánh giặc"},{"id":"b","text":"Chỉ nhà vua quyết định, dân không được biết"},{"id":"c","text":"Đại Việt muốn cầu hòa"}],"correct":"a","right":"Đúng. Bình Than là hội nghị của vương hầu, tướng lĩnh; Diên Hồng là hội nghị hỏi ý dân – từ triều đình tới nhân dân đều đồng lòng.","wrong":"Chưa đúng. Nhớ lại câu trả lời “Đánh!” của các bô lão."}]}$w$::jsonb) WHERE code = 'dien-hong' AND NOT (content ? 'world');
UPDATE public.hk_saga_stages SET content = content || jsonb_build_object('world', $w${"title":"Rút lui chiến lược","intro":"Quân Nguyên mạnh, muốn đánh nhanh thắng nhanh. Em cùng các bạn chuyển lương lên thuyền rút về Thiên Trường, rồi cùng quân Thánh Dực chặn giặc ở bãi Đà Mạc.","steps":[{"type":"talk","npc":"quoc_tuan","goal":"Gặp Trần Quốc Tuấn ở quân doanh.","lines":["Giặc mạnh, muốn đánh nhanh thắng nhanh. Đối đầu trực diện là trúng ý giặc.","Ta lui binh, làm vườn không nhà trống để triệt nguồn lương của giặc. Hãy giúp chuyển lương lên thuyền."]},{"type":"gather","res":"lua","count":4,"goal":"Gặt 4 lúa."},{"type":"craft","item":"bao","count":2,"goal":"Đóng 2 bao lương."},{"type":"place","item":"bao","zone":"thuyen_rut","count":2,"team":4,"goal":"Chất bao lương lên thuyền ở bến bờ tây: em chất 2, cả lớp cần 4."},{"type":"talk","npc":"binh_trong","goal":"Gặp tướng Trần Bình Trọng.","lines":["Ta sẽ chặn giặc ở bãi Đà Mạc để đại quân và dân chúng rút đi an toàn.","Ta thà làm ma nước Nam, chứ không thèm làm vương đất Bắc!"]},{"type":"battle","zone":"da_mac","goal":"Cùng quân Thánh Dực chặn giặc ở bãi Đà Mạc."},{"type":"zone","zone":"thien_truong","goal":"Theo đại quân lui về Thiên Trường.","lines":["Quân Trần lui về Thiên Trường, Trường Yên rồi vào Thanh Hóa để củng cố.","Ở ngoài bắc, quân Nguyên gặp nắng nóng, mưa lớn, bệnh tật và thiếu lương."]},{"type":"ask","npc":"quan_tt","goal":"Trả lời câu hỏi của viên quan Thiên Trường.","prompt":"Vì sao năm 1285 quân Trần rút khỏi Thăng Long?","options":[{"id":"a","text":"Không đối đầu khi giặc mạnh: lui binh giữ lực lượng, làm vườn không nhà trống để giặc thiếu lương"},{"id":"b","text":"Vì quân Trần đã thua hết"},{"id":"c","text":"Vì muốn nhường Thăng Long cho giặc mãi mãi"}],"correct":"a","right":"Đúng. Giữ quân chờ thời; khi giặc suy yếu thì phản công.","wrong":"Chưa đúng. Nhớ lời Trần Quốc Tuấn ở quân doanh."}]}$w$::jsonb) WHERE code = 'rut-lui-1285' AND NOT (content ? 'world');
UPDATE public.hk_saga_stages SET content = content || jsonb_build_object('world', $w${"title":"Tiếp tế cho trận Hàm Tử","intro":"Mùa hè năm 1285, quân Nguyên thiếu lương, bệnh tật. Em lo tiếp tế cho quân của Chiêu Văn vương Trần Nhật Duật: tìm đúng đường chở lương rồi cùng ra trận ở cửa Hàm Tử.","steps":[{"type":"talk","npc":"nhat_duat","goal":"Qua sông gặp Chiêu Văn vương Trần Nhật Duật.","lines":["Giặc không hợp thủy thổ, gặp mùa hè nóng bức, mưa lớn, bệnh tật, lại thiếu lương. Thời cơ phản công đã tới!","Ta làm chánh tướng đánh giặc ở Hàm Tử. Quân cần lương – em lo việc tiếp tế."]},{"type":"talk","npc":"trieu_trung","goal":"Gặp tướng Triệu Trung.","lines":["Ta là người Tống cũ, sang theo Đại Việt. Quân ta mang cờ hiệu và áo quân Tống.","Thấy vậy, quân Nguyên sẽ lo lắng tưởng nhà Tống đã khôi phục."]},{"type":"gather","res":"lua","count":4,"goal":"Gặt 4 lúa."},{"type":"craft","item":"bao","count":2,"goal":"Đóng 2 bao lương."},{"type":"pick","zones":["duong_rung","duong_song","duong_nui"],"correct":"duong_song","award":"route:tiep-te-1285","goal":"Đọc bản đồ, tìm đúng đường chở lương tới Hàm Tử (Lối rừng, Bến sông phía nam hay Lối núi).","clue":"Đường nào nối thẳng tới Hàm Tử mà chở được nhiều lương nhất?","right":"Đúng! Đường sông vừa nhanh vừa chở được nhiều lương; thuyền tiếp tế xuôi thẳng tới Hàm Tử.","wrong":"Đường này xa và khó chở lương. Xem lại bản đồ: đường nào nối thẳng tới Hàm Tử?"},{"type":"give","npc":"hoa_dau","item":"bao","count":2,"goal":"Mang 2 bao lương tới hỏa đầu quân bên Hàm Tử.","lines":["Có lương rồi, quân sĩ no bụng mới đánh được giặc!"]},{"type":"battle","zone":"ham_tu","goal":"Cùng quân Trần Nhật Duật đánh giặc ở cửa Hàm Tử."},{"type":"ask","npc":"nhat_duat","goal":"Trả lời câu hỏi của Trần Nhật Duật.","prompt":"Vì sao lúc này là thời cơ phản công?","options":[{"id":"a","text":"Giặc suy yếu vì thiếu lương, bệnh tật và thời tiết mùa hè"},{"id":"b","text":"Vì giặc đã về nước hết"},{"id":"c","text":"Vì quân Trần có voi chiến mới"}],"correct":"a","right":"Đúng. Thắng ở Hàm Tử, quân Trần có bàn đạp tiến đánh Thăng Long.","wrong":"Chưa đúng. Nhớ lại tình cảnh của quân Nguyên mùa hè năm ấy."}]}$w$::jsonb) WHERE code = 'ham-tu' AND NOT (content ? 'world');
UPDATE public.hk_saga_stages SET content = content || jsonb_build_object('world', $w${"title":"Đánh vào bến thuyền Chương Dương","intro":"Sau Hàm Tử, quân Trần ra bắc lấy lại Thăng Long. Em cùng các bạn đóng thuyền nhẹ, tập kết ở bến bờ tây rồi theo Trần Quang Khải đánh vào bến thuyền Chương Dương.","steps":[{"type":"talk","npc":"quang_khai","goal":"Gặp Thượng tướng thái sư Trần Quang Khải ở bờ tây.","lines":["Ta làm chánh tướng, Phạm Ngũ Lão và Trần Quốc Toản làm phó tướng. Ta đem quân ra bắc lấy lại Thăng Long.","Đại quân Thoát Hoan sắp cạn lương, chiến thuyền đậu ở bến Chương Dương."]},{"type":"talk","npc":"ngu_lao","goal":"Gặp phó tướng Phạm Ngũ Lão.","lines":["Quân Nguyên quen thấy ta thua, nay bị đánh mạnh sẽ bất ngờ.","Cần thêm thuyền nhẹ để áp sát bến giặc."]},{"type":"gather","res":"go","count":4,"goal":"Lấy 4 gỗ để đóng thuyền."},{"type":"gather","res":"tre","count":2,"goal":"Lấy 2 tre."},{"type":"craft","item":"thuyen","count":2,"goal":"Đóng 2 thuyền nhẹ."},{"type":"place","item":"thuyen","zone":"ben_tap_ket","count":2,"team":4,"goal":"Đưa thuyền ra bến tập kết bờ tây: em đưa 2 chiếc, cả lớp cần 4 chiếc."},{"type":"battle","zone":"chuong_duong","goal":"Vượt sông đánh vào bến thuyền Chương Dương."},{"type":"talk","npc":"quang_khai","goal":"Về báo tin thắng trận với Trần Quang Khải.","lines":["Thắng rồi! Phần lớn chiến thuyền giặc bị đốt cháy hoặc bị chiếm; quân dân vây đánh, giặc phải bỏ Thăng Long.","Ta làm bài thơ: “Đoạt sáo Chương Dương độ, / Cầm Hồ Hàm Tử quan…” – Chương Dương cướp giáo giặc, Hàm Tử bắt quân thù."]},{"type":"ask","npc":"quang_khai","goal":"Trả lời câu hỏi của Trần Quang Khải.","prompt":"Vì sao quân Trần đánh vào bến thuyền Chương Dương?","options":[{"id":"a","text":"Chiến thuyền giặc tập trung ở đó; đánh bến thuyền làm giặc mất phương tiện và tan tác"},{"id":"b","text":"Vì bến Chương Dương có nhiều cá"},{"id":"c","text":"Để mời giặc đàm phán"}],"correct":"a","right":"Đúng. Mất thuyền lại cạn lương, quân Nguyên không giữ nổi Thăng Long.","wrong":"Chưa đúng. Nhớ lại nơi chiến thuyền của Thoát Hoan đậu."}]}$w$::jsonb) WHERE code = 'chuong-duong' AND NOT (content ? 'world');
UPDATE public.hk_saga_stages SET content = content || jsonb_build_object('world', $w${"title":"Trận Tây Kết","intro":"Thoát Hoan đã thua chạy, nhưng đạo quân của Toa Đô từ phía nam vẫn không hay biết. Em cùng các bạn chặn đường rút của giặc rồi tấn công Tây Kết.","steps":[{"type":"talk","npc":"quoc_tuan","goal":"Gặp Trần Quốc Tuấn ở quân doanh.","lines":["Toa Đô đem quân từ phía nam đánh ra để hợp với Thoát Hoan. Thoát Hoan đã thua chạy mà Toa Đô vẫn không hay biết.","Đạo quân ấy bị cô lập ở Tây Kết. Hãy chặn đường rút của chúng."]},{"type":"gather","res":"go","count":2,"goal":"Lấy 2 gỗ."},{"type":"gather","res":"tre","count":2,"goal":"Lấy 2 tre."},{"type":"craft","item":"rao","count":2,"goal":"Làm 2 rào chắn (mỗi rào 1 gỗ + 1 tre)."},{"type":"place","item":"rao","zone":"chan_duong","count":2,"team":4,"goal":"Chặn con đường rút của giặc bên Tây Kết: em dựng 2 rào, cả lớp cần 4."},{"type":"talk","npc":"truong_hien","goal":"Gặp Trương Hiển, tổng quản quân Nguyên vừa xin hàng.","lines":["Ta là Trương Hiển, tổng quản quân Nguyên. Ta xin hàng và sẽ dẫn đường cho quân Trần."]},{"type":"battle","zone":"tay_ket","goal":"Tấn công đạo quân Toa Đô ở Tây Kết."},{"type":"ask","npc":"linh_tk","goal":"Trả lời câu hỏi của người lính.","prompt":"Vì sao cuộc kháng chiến lần thứ hai thắng lợi?","options":[{"id":"a","text":"Chuẩn bị từ sớm, cả nước đồng lòng, lui quân giữ sức làm giặc thiếu lương, rồi phản công đúng lúc"},{"id":"b","text":"Vì quân Nguyên tự bỏ về"},{"id":"c","text":"Vì có bão lớn đánh chìm thuyền giặc"}],"correct":"a","right":"Đúng! Đó là bài học của năm 1285.","wrong":"Chưa đúng. Nhớ lại Bình Than, Diên Hồng, cuộc rút lui và các trận phản công."}]}$w$::jsonb) WHERE code = 'tay-ket' AND NOT (content ? 'world');
